  const formOn = (v) => v === true || /^(yes|true|on|checked|remote control)$/i.test(String(v ?? '').trim());
  const formNum = (v) => { const n = parseFloat(String(v ?? '').replace(/[^0-9.+-]/g, '')); return Number.isFinite(n) ? n : null; };
  const r1 = (x) => Math.round(x * 10) / 10;
