  const fullLoadAmps = (kw) => r1(kw * 1000 / (Math.sqrt(3) * 415 * 0.85 * 0.9));
  const formRulesFor = (e) => { const R = window.FORM_RULES || {}; return (e && (R[e.dbType] || R[e.code])) || []; };
  const ruleHits = (r, f) => { const v = f ? f[r.q] : undefined; if (v == null || v === '') return false; if (r.on) return formOn(v); if (r.when == null) return true; return typeof r.when.test === 'function' ? r.when.test(String(v)) : formOn(r.when) ? formOn(v) : String(v).trim().toLowerCase() === String(r.when).toLowerCase(); };
  /* m³ from Shape and the dimensions (metres): cylindrical π r² h, cuboid l × w × h. The Oil & Grease Tank's form asks 'Breath'. */
  const volumeOf = (f) => { const g = (k) => formNum(f[k]); const h = g('Depth / Height') ?? g('Height'); const r = g('Radius'), l = g('Length'), w = g('Width') ?? g('Breadth') ?? g('Breath'); if (h == null) return null; const shape = String(f.Shape || (r != null ? 'cylindrical' : 'cuboid')).toLowerCase(); const v = shape.startsWith('cyl') ? (r != null ? Math.PI * r * r * h : null) : (l != null && w != null ? l * w * h : null); return v != null ? Math.round(v) : null; };
  /* facts the rules keep on the machine */
  function applyFormRules(e) { const f = e.form; e.derived = {}; ['vfd', 'remote', 'overflow', 'valveType', 'pumpType'].forEach((k) => { delete e[k]; }); if (!f) return; formRulesFor(e).forEach((r) => { if (!ruleHits(r, f)) return; const v = f[r.q]; if (r.reads === 'flag') { e[r.field] = r.on ? true : String(v).trim().toLowerCase(); return; } if (r.reads === 'expects') { e[r.field] = true; return; } if (r.derive === 'volume') { const vol = volumeOf(f); if (vol != null) e.derived.volume = vol; return; } if (r.derive === 'fla') { const kw = formNum(v); if (kw != null) { e.derived[r.key] = fullLoadAmps(kw); e.derived[r.raw || 'kw'] = kw; } return; } if (r.derive === 'number') { const n = formNum(v); if (n != null) e.derived[r.key] = n; } }); }
