  function fitValid(e, s) { if (!e || !e.derived || !s || !Array.isArray(s.valid) || s.nextPhase) return s; for (const r of formRulesFor(e)) { if (r.reads !== 'limits' || r.sensorKind !== s.name) continue; const base = e.derived[r.key]; if (base == null) continue; const top = Math.ceil(2 * base / (r.per || 1)); if (top > s.valid[1]) s.valid = [s.valid[0], top]; } return s; }
  /* limits a form answer gives one of this machine's readings on the equipment: a motor rating → full-load amps → motor current */
  function derivedLimits(e, sensorKind) { if (!e || !e.derived || onConnection(sensorKind)) return null; for (const r of formRulesFor(e)) { if (r.reads !== 'limits' || r.sensorKind !== sensorKind) continue; const base = e.derived[r.key]; if (base == null) continue; const per = r.per || 1; const lim = { caution: null, minor: null, major: null, emergency: null }; Object.keys(r.factors).forEach((k) => { lim[k] = r1(r.factors[k] * base / per); }); const raw = r.raw && e.derived[r.raw] != null ? e.derived[r.raw] : base; return { lim, dir: r.direction, why: `from the SCADA form: ${String(r.why).replace('{v}', raw)}` }; } return null; }
