  function formItems(e) { const f = e.form, alerts = [], schedules = [], adjust = {}; if (!f) return { alerts, schedules, adjust }; formRulesFor(e).forEach((r) => { if (!ruleHits(r, f)) return; const v = f[r.q]; if (r.reads === 'expects' && r.alert) alerts.push({ ...clone(r.alert), fromForm: true }); if (r.schedule) { const s = clone(r.schedule); (r.everyBy || []).forEach(([re, ev]) => { if (re.test(String(v))) s.every = { ...ev }; }); (r.partsBy || []).forEach(([q2, re, note]) => { if (re.test(String(f[q2] ?? ''))) s.parts = s.parts ? `${s.parts} · ${note}` : note; }); s.fromForm = true; schedules.push(s); } if (r.adjust) { const a = adjust[r.adjust] = adjust[r.adjust] || {}; const n = formNum(v); if (r.doWhen != null && n != null) { a.doWhen = Math.round(n * r.doWhen); a.doneWhen = Math.round(n * r.doneWhen); } if (r.set) Object.assign(a, r.set); if (r.partsNote && n != null) a.partsNote = String(r.partsNote).replace('{v}', n); } }); return { alerts, schedules, adjust }; }
